function applyKitListUpdate() {
  var ui = SpreadsheetApp.getUi();
  var response = ui.alert('Confirmation', 'Launch Kit List update?', ui.ButtonSet.YES_NO);

  if (response == ui.Button.NO) {
    return; // Stop if the user says no
  }

  // Open the master sheet
  var masterSheet = SpreadsheetApp.openByUrl('https://docs.google.com/spreadsheets/d/1kgGvJRr5fTTG31LzxuGIvOSeuXWoHudVko-VYJCHpWI/edit');
  var kitListSource = masterSheet.getSheetByName("Kit Lists");

  if (!kitListSource) {
    Logger.log("Error: 'Kit Lists' tab not found in the master sheet.");
    return;
  }

  var sourceData = kitListSource.getDataRange().getValues();
  var sourceColumnWidths = [];
  for (var col = 1; col <= kitListSource.getLastColumn(); col++) {
    sourceColumnWidths.push(kitListSource.getColumnWidth(col));
  }

  // Retrieve the salesmen details from the "Update Wizard" tab in the master sheet
  var wizardSheet = masterSheet.getSheetByName("Update Wizard");
  var salesmenData = wizardSheet.getRange("A2:C").getValues(); // Assuming data starts at row 2, columns A (names) and C (URLs)

  // Loop through each salesman's file
  salesmenData.forEach(function(row) {
    var name = row[0].trim(); // Salesman's name from column A, trimmed to avoid extra spaces
    var fileUrl = row[2]; // File URL of the salesman's sheet from column C

    if (name && fileUrl) {
      try {
        Logger.log("Processing " + name + " with file URL: " + fileUrl);

        // Open the target spreadsheet
        var targetSs = SpreadsheetApp.openByUrl(fileUrl);
        var kitListTarget = targetSs.getSheetByName("Kit Lists");

        if (!kitListTarget) {
          kitListTarget = targetSs.insertSheet("Kit Lists");
        }

        var targetRange = kitListTarget.getRange(1, 1, sourceData.length, sourceData[0].length);
        targetRange.setValues(sourceData); // Overwrite data

        // Match column widths
        for (var col = 1; col <= sourceColumnWidths.length; col++) {
          kitListTarget.setColumnWidth(col, sourceColumnWidths[col - 1]);
        }

        // Protect the sheet from edits except for authorized users
        var protection = kitListTarget.protect();
        protection.setDescription("Protected Kit Lists");
        protection.removeEditors(protection.getEditors()); // Remove all editors
        protection.setWarningOnly(false); // Fully protect the sheet

        // Hide the sheet
        kitListTarget.hideSheet();

        Logger.log("Successfully updated 'Kit Lists' tab for " + name);
      } catch (e) {
        Logger.log("Error processing " + name + ": " + e.message);
      }
    } else {
      Logger.log("Error: Missing file URL for '" + name + "'.");
    }
  });

  // Set the most recent run date in F3 of the "Update Wizard" tab
  wizardSheet.getRange("F3").setValue(new Date());

  SpreadsheetApp.getUi().alert("Kit List update applied to all target sheets successfully.");
}

function copyCheckboxesToTargetFiles() {
  var ui = SpreadsheetApp.getUi();
  var response = ui.alert('Confirmation', 'Are you sure you want to copy checkboxes to all target files?', ui.ButtonSet.YES_NO);

  // Proceed only if the user clicks "Yes"
  if (response == ui.Button.YES) {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var masterSheet = ss.getSheetByName("Material Input"); // Master file's "Material Input" tab

    // Define ranges for checkboxes
    var checkboxRanges = ['H3:H41', 'M3:M41', 'R3:R', 'W3:W']; // List of ranges with checkboxes
    // Get the URLs of target salesmen's sheets from the "Update Wizard" tab
    var wizardSheet = ss.getSheetByName('Update Wizard'); // Replace with the actual tab name
    var urlRange = wizardSheet.getRange('C2:C'); // Assuming URLs are in column B starting from row 2
    var urls = urlRange.getValues().filter(String); // Get all URLs and filter out any blanks

    // Loop through each target URL and copy checkboxes to the "Material Input" tab in each file
    urls.forEach(function(row) {
      var targetUrl = row[0];
      if (targetUrl && targetUrl !== "-") { // Skip if the URL is a dash ("-")
        try {
          var targetSpreadsheet = SpreadsheetApp.openByUrl(targetUrl);
          var targetSheet = targetSpreadsheet.getSheetByName("Material Input"); // Ensure "Material Input" exists in target

          if (targetSheet) {
            // Loop through each checkbox range
            checkboxRanges.forEach(function(rangeStr) {
              var masterRange = masterSheet.getRange(rangeStr);
              var targetRange = targetSheet.getRange(rangeStr);
              var masterValues = masterRange.getValues();
              var masterValidations = masterRange.getDataValidations();

              // Copy data validation for checkboxes while ignoring cells containing "~"
              for (var i = 0; i < masterValues.length; i++) {
                for (var j = 0; j < masterValues[i].length; j++) {
                  if (masterValues[i][j] !== "~") {
                    targetRange.getCell(i + 1, j + 1).setDataValidation(masterValidations[i][j]);
                  }
                }
              }
            });
          } else {
            Logger.log("No 'Material Input' tab found in " + targetUrl);
          }
        } catch (e) {
          Logger.log("Error accessing file: " + targetUrl + ". " + e.message);
        }
      }
    });

    // Show confirmation message after all URLs have been processed
    ui.alert('Checkboxes have been successfully copied to all target files.');
  } else {
    ui.alert('Operation canceled. No checkboxes were copied.');
  }
}

function generateChecklist() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var input = ss.getSheetByName('Material Input');
  if (!input) {
    SpreadsheetApp.getUi().alert('Sheet "Material Input" not found.');
    return;
  }

  // — Generate or replace the Checklist sheet —
  var old = ss.getSheetByName('Checklist');
  if (old) ss.deleteSheet(old);
  var cl = ss.insertSheet('Checklist');
  cl.appendRow(['Category', 'Name', 'Quantity', 'Done']);

  // Pull in everything from col-E/J/O/T (cat), F/K/P/U (name), G/L/Q/V (qty)
  var lastInputRow = input.getLastRow();
  if (lastInputRow < 2) {
    SpreadsheetApp.getUi().alert('No data to process.');
    return;
  }
  var data = input.getRange(2, 1, lastInputRow - 1, 22).getValues();
  var catCols  = [5, 10, 15, 20];
  var nameCols = [6, 11, 16, 21];
  var qtyCols  = [7, 12, 17, 22];

  // Build the sheet output
  var output = [];
  data.forEach(function(row) {
    for (var i = 0; i < catCols.length; i++) {
      var q = row[qtyCols[i] - 1];
      if (typeof q === 'number' && q > 0) {
        output.push([
          row[catCols[i] - 1],
          row[nameCols[i] - 1],
          q,
          false
        ]);
      }
    }
  });
  if (output.length === 0) {
    SpreadsheetApp.getUi().alert('No positive quantities found.');
    return;
  }

  // Write it, add checkboxes, borders, auto-resize
  cl.getRange(2, 1, output.length, 4).setValues(output);
  cl.getRange(2, 4, output.length, 1).insertCheckboxes();
  var lastRow = cl.getLastRow();
  cl.getRange(1, 1, lastRow, 4)
    .setBorder(true, true, true, true, true, true);
  for (var c = 1; c <= 4; c++) cl.autoResizeColumn(c);

  // Grab the displayed (string) values for print
  var tableValues = cl.getRange(1,1,lastRow,4).getDisplayValues();

  // Show an HTML dialog that renders exactly that table and auto-prints
  var tpl = HtmlService.createTemplateFromFile('PrintChecklist');
  tpl.values = tableValues;
  var html = tpl.evaluate()
    .setWidth(800).setHeight(600);
  SpreadsheetApp.getUi().showModalDialog(html, 'Print Checklist');
}

function clearChangeOutKits() {
  const ui = SpreadsheetApp.getUi();
  const confirmation = ui.alert(
    "Clear Selection?",
    "Are you sure you want to clear your current kits?",
    ui.ButtonSet.YES_NO
  );

  if (confirmation !== ui.Button.YES) {
    ui.alert("Operation canceled.");
    return;
  }

  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Change Out Kits");

  if (!sheet) {
    ui.alert("Change Out Kits tab not found.");
    return;
  }

  // Clear E4:F of the Change Out Kits tab
  sheet.getRange("E4:F" + sheet.getLastRow()).clearContent();
  ui.alert("Pending Materials Cleared");
}

function resetMaterialInput() {
  var ui = SpreadsheetApp.getUi();
  var response = ui.alert('Confirmation', 'Are you sure you want to clear the template? This cannot be undone!', ui.ButtonSet.YES_NO);

  if (response == ui.Button.NO) {
    return; // Halt the function if user selects NO
  }

  var sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Material Input");

  // Clear the specified ranges in the "Material Input" tab unless the cell contains "~"
  clearCells(sheet, 'C4:C7');
  clearCells(sheet, 'G3:G');  // Adjust range based on new layout
  clearCells(sheet, 'L3:L');  // Adjust range based on new layout
  clearCells(sheet, 'Q3:Q');  // Adjust range based on new layout
  clearCells(sheet, 'V3:V');  // Adjust range based on new layout

  // Set F3:F41 to "ENTER MODEL NUMBER HERE"
  sheet.getRange('F3:F41').setValue('ENTER MODEL NUMBER HERE');

  // Set K3:K41 to "ENTER DIMENSIONS HERE"
  sheet.getRange('K3:K41').setValue('ENTER DIMENSIONS HERE');

  // Update P44:P87 to "NAME AND MODEL NUMBER OR DIMENSIONS"
  sheet.getRange('P44:P87').setValue('NAME AND MODEL NUMBER OR DIMENSIONS');
}

// Helper function to clear a range unless the cell contains "~"
function clearCells(sheet, rangeStr) {
  var range = sheet.getRange(rangeStr);
  var values = range.getValues();

  for (var i = 0; i < values.length; i++) {
    for (var j = 0; j < values[i].length; j++) {
      if (values[i][j] !== "~") {
        values[i][j] = "";
      }
    }
  }

  range.setValues(values);
}

function clearSearch() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName('Material Input');
  if (!sheet) return;

  sheet.getRange('C26').setValue('');
  sheet.getRange('C28').setValue('');
  sheet.getRange('C32').clearContent();

  SpreadsheetApp.getUi().alert('Search Cleared.');
}

function runMaterialUpdate() {
  const ui = SpreadsheetApp.getUi();
  const confirmation = ui.alert(
    "Confirm Selection?",
    "Do you want to add quantities to the material input tab?",
    ui.ButtonSet.YES_NO
  );

  if (confirmation !== ui.Button.YES) {
    ui.alert("Operation canceled.");
    return;
  }

  const changeOutSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Change Out Kits");
  const materialInputSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Material Input");

  if (!changeOutSheet || !materialInputSheet) {
    ui.alert("Required sheets not found.");
    return;
  }

  const materialNames = changeOutSheet.getRange("F4:F" + changeOutSheet.getLastRow()).getValues().flat();
  const materialQuantities = changeOutSheet.getRange("E4:E" + changeOutSheet.getLastRow()).getValues().flat();

  materialNames.forEach((material, index) => {
    if (material) {
      const quantity = materialQuantities[index] || 0;

      const materialInputDataP = materialInputSheet.getRange("P2:P" + materialInputSheet.getLastRow()).getValues().flat();
      const materialInputDataQ = materialInputSheet.getRange("Q2:Q" + materialInputSheet.getLastRow()).getValues().flat();
      const materialInputDataU = materialInputSheet.getRange("U2:U" + materialInputSheet.getLastRow()).getValues().flat();
      const materialInputDataV = materialInputSheet.getRange("V2:V" + materialInputSheet.getLastRow()).getValues().flat();

      const matchInP = materialInputDataP.indexOf(material);
      const matchInU = materialInputDataU.indexOf(material);

      if (matchInP !== -1) {
        const targetCell = materialInputSheet.getRange(matchInP + 2, 17); // Column Q
        const existingQuantity = targetCell.getValue() || 0;
        targetCell.setValue(existingQuantity + quantity);
      }

      if (matchInU !== -1) {
        const targetCell = materialInputSheet.getRange(matchInU + 2, 22); // Column V
        const existingQuantity = targetCell.getValue() || 0;
        targetCell.setValue(existingQuantity + quantity);
      }
    }
  });

  // Clear E4:F of the Change Out Kits tab
  changeOutSheet.getRange("E4:F" + changeOutSheet.getLastRow()).clearContent();

  ui.alert("Selected kit materials have been added to the Material List.");
}

/***********************
* CORE FUNCTIONS
***********************/
var _cache = { lastFetch: 0, data: {} };
function getCachedRange(sheet, range) {
  var cacheKey = sheet.getName() + '|' + range;
  var now = Date.now();
  if (!_cache.data[cacheKey] || now - _cache.lastFetch > 300) {
    _cache.data[cacheKey] = sheet.getRange(range).getValues();
    _cache.lastFetch = now;
  }
  return _cache.data[cacheKey];
}

function findMatchingCategories(category) {
  var sheet = SpreadsheetApp.getActive().getSheetByName('Material Input');
  var values = sheet.getRange("O44:O88").getValues();
  var matches = [];
  for (var i = 0; i < values.length; i++) {
    if (values[i][0] === category) {
      matches.push(i + 44);
    }
  }
  return matches;
}

function clearQuantities() {
  var sheet = SpreadsheetApp.getActive().getSheetByName('Material Input');
  var ranges = [
    { col: 12, itemCol: 11 },
    { col: 17, itemCol: 16 },
    { col: 22, itemCol: 21 }
  ];
  ranges.forEach(function(r) {
    var values = sheet.getRange(3, r.col, sheet.getLastRow() - 2, 1).getValues();
    var items = sheet.getRange(3, r.itemCol, sheet.getLastRow() - 2, 1).getValues();
    for (var i = 0; i < values.length; i++) {
      if (items[i][0] !== '~') { values[i][0] = ''; }
    }
    sheet.getRange(3, r.col, values.length, 1).setValues(values);
  });
  sheet.getRange('K3:K41').setValue('ENTER DIMENSIONS HERE');
  sheet.getRange('O44:O88').setValue('SPECIFIC MATERIALS');
  sheet.getRange('P44:P88').setValue('NAME AND MODEL NUMBER OR DIMENSIONS');
  sheet.getRange('Q44:Q88').clearContent();
}

/***********************
* SAVE FUNCTION
***********************/
function saveMaterialsToCustomList() {
  var ss = SpreadsheetApp.getActive();
  var inputSheet = ss.getSheetByName('Material Input');
  var storageSheet = ss.getSheetByName('Custom List Storage');
  var ui = SpreadsheetApp.getUi();
  var kitName = storageSheet.getRange('D2').getValue();
  if (!kitName) {
    var resp = ui.prompt('Save Kit', 'Enter kit name:', ui.ButtonSet.OK_CANCEL);
    if (resp.getSelectedButton() !== ui.Button.OK || !resp.getResponseText()) return;
    kitName = resp.getResponseText().trim();
  }
  var finalData = [];
  var ductCat = inputSheet.getRange('J3:J41').getValues();
  var ductName = inputSheet.getRange('K3:K41').getValues();
  var ductQty = inputSheet.getRange('L3:L41').getValues();
  for (var i = 0; i < ductQty.length; i++) {
    var qty = ductQty[i][0], name = ductName[i][0], cat = ductCat[i][0];
    if (qty && name && name !== 'ENTER DIMENSIONS HERE') {
      finalData.push([kitName, cat + ' - ' + name, qty]);
    }
  }
  var lastRow = inputSheet.getLastRow();
  var equipData = inputSheet.getRange('P3:Q' + lastRow).getValues();
  for (var i = 0; i < equipData.length; i++) {
    var item = equipData[i][0], qty = equipData[i][1];
    if (item && qty && item !== '~' && item !== 'NAME AND MODEL NUMBER OR DIMENSIONS') {
      var absRow = i + 3;
      if (absRow >= 44 && absRow <= 88) {
        finalData.push([kitName, "SPECIFIC MATERIALS - " + item, qty]);
      } else {
        finalData.push([kitName, item, qty]);
      }
    }
  }
  var stockData = inputSheet.getRange('U3:V' + lastRow).getValues();
  for (var i = 0; i < stockData.length; i++) {
    var item = stockData[i][0], qty = stockData[i][1];
    if (item && qty && item !== '~') {
      finalData.push([kitName, item, qty]);
    }
  }
  if (finalData.length === 0) {
    ui.alert('Error: No valid materials with quantities to save');
    return;
  }
  var storageData = storageSheet.getRange('A2:C' + storageSheet.getLastRow()).getValues();
  var filtered = storageData.filter(function(row) { return row[0] !== kitName; });
  var newData = filtered.concat(finalData);
  storageSheet.getRange(2, 1, newData.length, 3).setValues(newData);
  storageSheet.getRange('D2').clearContent();
  clearQuantities();
  ui.alert('Kit "' + kitName + '" saved successfully');
}

/***********************
* LOADER HELPERS
***********************/
function loadDuctworkAndSpecMat(kitData, inputSheet) {
  var specificIndex = 0;
  var ductIndex = 0;
  kitData.forEach(function(row) {
    var savedItem = row[1], qty = row[2];
    if (savedItem.indexOf("SPECIFIC MATERIALS - ") === 0) {
      var actualItem = savedItem.replace("SPECIFIC MATERIALS - ", "").trim();
      var itemCol = inputSheet.getRange("P44:P88").getValues();
      for (var i = specificIndex; i < itemCol.length; i++) {
        if (!itemCol[i][0] || itemCol[i][0] === 'NAME AND MODEL NUMBER OR DIMENSIONS') {
          var rowIndex = i + 44;
          inputSheet.getRange(rowIndex, 15).setValue("SPECIFIC MATERIALS");
          inputSheet.getRange(rowIndex, 16).setValue(actualItem);
          inputSheet.getRange(rowIndex, 17).setValue(qty);
          specificIndex = i + 1;
          break;
        }
      }
    } else if (savedItem.indexOf(' - ') > -1) {
      var parts = savedItem.split(' - ');
      var cat = parts[0], itemName = parts.slice(1).join(' - ');
      var ductCat = inputSheet.getRange('J3:J41').getValues();
      for (var i = ductIndex; i < ductCat.length; i++) {
        if (ductCat[i][0] === cat && inputSheet.getRange(i + 3, 11).getValue() === 'ENTER DIMENSIONS HERE') {
          inputSheet.getRange(i + 3, 11).setValue(itemName);
          inputSheet.getRange(i + 3, 12).setValue(qty);
          ductIndex = i + 1;
          break;
        }
      }
    }
  });
}

function loadEquipmentAndStockItems(kitData, inputSheet) {
  var lastRow = inputSheet.getLastRow();
  kitData.forEach(function(row) {
    var savedItem = row[1], qty = row[2];
    if (savedItem.indexOf("SPECIFIC MATERIALS - ") !== 0 && savedItem.indexOf(' - ') === -1) {
      var equipRange = inputSheet.getRange('P3:P' + lastRow).getValues().flat();
      var loaded = false;
      for (var i = 0; i < equipRange.length; i++) {
        if (equipRange[i] === savedItem) {
          inputSheet.getRange(i + 3, 17).setValue(qty);
          loaded = true;
          break;
        }
      }
      if (!loaded) {
        var stockRange = inputSheet.getRange('U3:U' + lastRow).getValues().flat();
        for (var i = 0; i < stockRange.length; i++) {
          if (stockRange[i] === savedItem) {
            inputSheet.getRange(i + 3, 22).setValue(qty);
            break;
          }
        }
      }
    }
  });
}

